import json
from sqlalchemy import select,func
from app.database import SessionLocal
from app.models import Source,SourceOpportunity,Opportunity,AuditEvent,SyncJob,OpportunityLocation,GeographicReferenceUnit
with SessionLocal() as db:
 src=db.scalar(select(Source).where(Source.source_key=='rcjy-investment-opportunities'))
 rows=db.scalars(select(SourceOpportunity).where(SourceOpportunity.source_id==src.id).order_by(SourceOpportunity.source_opportunity_id)).all()
 job=db.scalar(select(SyncJob).where(SyncJob.source_id==src.id).order_by(SyncJob.id.desc()).limit(1))
 masters=[db.get(Opportunity,row.master_opportunity_id) for row in rows if row.master_opportunity_id]
 data={'configured_sources':db.scalar(select(func.count(Source.id))),'enabled_sources':db.scalar(select(func.count(Source.id)).where(Source.enabled.is_(True))),'current_masters':db.scalar(select(func.count(Opportunity.id)).where(Opportunity.merged_into_id.is_(None))),'all_master_rows':db.scalar(select(func.count(Opportunity.id))),'merged_masters':db.scalar(select(func.count(Opportunity.id)).where(Opportunity.merged_into_id.is_not(None))),'source_opportunities':db.scalar(select(func.count(SourceOpportunity.id))),'rcjy_source_rows':len(rows),'rcjy_linked_rows':sum(bool(r.master_opportunity_id) for r in rows),'rcjy_unlinked_rows':sum(not r.master_opportunity_id for r in rows),'masters_without_source':db.scalar(select(func.count(Opportunity.id)).where(Opportunity.merged_into_id.is_(None),~Opportunity.source_records.any())),'rcjy_duplicate_provider_keys':db.scalar(select(func.count()).select_from(select(SourceOpportunity.source_opportunity_id).where(SourceOpportunity.source_id==src.id).group_by(SourceOpportunity.source_opportunity_id).having(func.count()>1).subquery())),'rcjy_master_audit_events':db.scalar(select(func.count(AuditEvent.id)).where(AuditEvent.event_type=='RCJY_MASTER_CREATED')),'rcjy_sync_job':{'id':job.id,'status':job.status,'raw_count':job.raw_count,'unique_records':job.unique_records,'new_count':job.new_count,'update_count':job.update_count,'removed_records_count':job.removed_records_count,'ahsa_count':job.ahsa_count,'pagination_complete':job.pagination_complete,'source_total_reported':job.source_total_reported,'trigger_type':job.trigger_type,'metrics':job.metrics_json},'masters':[{'id':m.id,'canonical_id':m.canonical_id,'title':m.title_ar,'sector':m.sector,'status':m.status,'city':m.city,'geo_scope':m.geographic_scope,'geography_reference_unit_id':m.geography_reference_unit_id,'owner':m.opportunity_owner,'coords':[m.latitude,m.longitude]} for m in masters]}
 print(json.dumps(data,ensure_ascii=False,default=str))

